package com.worldgenv2.positions;

import com.worldgenv2.vector.Vec3d;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * Spawns clusters of randomized sub-points around anchor sites generated by a parent {@link PositionsProvider}.
 */
public final class ClustersPositionsProvider implements PositionsProvider {

    private final PositionsProvider parent;
    private final int pointsPerCluster;
    private final double clusterRadius;
    private final long seed;

    public ClustersPositionsProvider(PositionsProvider parent, int pointsPerCluster, double clusterRadius, long seed) {
        this.parent = Objects.requireNonNull(parent, "parent");
        this.pointsPerCluster = Math.max(1, pointsPerCluster);
        this.clusterRadius = Math.max(0.1, clusterRadius);
        this.seed = seed;
    }

    public PositionsProvider parent() {
        return parent;
    }

    public int pointsPerCluster() {
        return pointsPerCluster;
    }

    public double clusterRadius() {
        return clusterRadius;
    }

    public long seed() {
        return seed;
    }

    @Override
    public List<Vec3d> getPositions(double minX, double minY, double minZ, double maxX, double maxY, double maxZ) {
        // Query parent centers with padding of clusterRadius
        List<Vec3d> centers = parent.getPositions(
            minX - clusterRadius, minY - clusterRadius, minZ - clusterRadius,
            maxX + clusterRadius, maxY + clusterRadius, maxZ + clusterRadius
        );

        List<Vec3d> result = new ArrayList<>(centers.size() * pointsPerCluster);
        for (Vec3d center : centers) {
            long siteSeed = seed ^ (Double.doubleToLongBits(center.x()) * 3129871L) ^ (Double.doubleToLongBits(center.z()) * 116129781L);
            java.util.Random rnd = new java.util.Random(siteSeed);

            for (int i = 0; i < pointsPerCluster; i++) {
                double angle = rnd.nextDouble() * 2.0 * Math.PI;
                double dist = rnd.nextDouble() * clusterRadius;
                double px = center.x() + Math.cos(angle) * dist;
                double py = center.y() + (rnd.nextDouble() * 2.0 - 1.0) * (clusterRadius * 0.25);
                double pz = center.z() + Math.sin(angle) * dist;

                if (px >= minX && px <= maxX && py >= minY && py <= maxY && pz >= minZ && pz <= maxZ) {
                    result.add(new Vec3d(px, py, pz));
                }
            }
        }
        return result;
    }
}
